10. Instruction: Write a JavaScript function that takes two strings and returns true if they are anagrams, otherwise it should return false.
10. Input:
<noinput>
10. Output:
falseuser

function isAnagram(str1, str2) {
  str1 = str1.toLowerCase();
  str2 = str2.toLowerCase();

  let sortedStr1 = str1.split('').sort().join('');
  let sortedStr2 = str2.split('').sort().join('');

  return sortedStr1 === sortedStr2;
}assistant

