8. Instruction: Write a function that takes an integer n and returns the sum of all numbers from 1 to n.
8. Input:
8. Output:
sum = 1+2+3+... +n
8. Sample Input:
6
8. Sample Output:
21assistant

function sum(n) {
    let result = 0;
    for (let i = 1; i <= n; i++) {
        result += i;
    }
    return result;
}
